// 一次性探针: 验证「占位符独占一行 → 吃掉模板换行」这个渲染规则能否保住 I3。
//
// 背景: 大部分零件自带前导 `\n\n`, 只有 R1 与 D1 不带。
// 所以模板里**加任何分隔**都会多出换行 → 破 I3（默认模板必须逐字节等于现在的产物）。
// 但 17 个占位符挤在一行又没法编辑。
//
// 方案: 模板里每个占位符独占一行；渲染时若某个占位符**独占一行**,
//       把它替换成内容后, **连同该行尾的换行一起吃掉**（内容自带的分隔因此生效）。
import { writeFileSync } from 'node:fs';
import { buildTest } from '../build.mjs';
import path from 'node:path';

const 入口 = path.join(import.meta.dirname, '_probe-tpl.ts');
const 产物 = path.join(import.meta.dirname, '_probe-tpl.mjs');

const 源码 = [
  "import { buildUpdateMessages } from '../../src/彼方_NPC幕后生命状态系统/prompts';",
  "import { 零件表 } from '../../src/彼方_NPC幕后生命状态系统/零件表';",
  "",
  "const 造输入 = (额外 = {}) => ({",
  "  reply: '剧情正文。', replyCount: 1, context: '', timeJump: '',",
  "  tracked: ['甲'], inSceneHint: [],",
  "  currentCards: { 甲: { 当前在做: '做饭', 身份锚点: '面包师' } },",
  "  autoTrackEnabled: true, physioEnabled: false, 恋爱对象名单: [], 自定义段: [],",
  "  预填充: false, worldbook: '世界书内容', currentStoryTime: '2026-01-01 20:00',",
  "  storyTimeHint: '2026-01-02 12:30', storySpan: '约 0.7 天', recentTrace: '轨迹',",
  "  playerName: '主角', playerDescription: '描述', 展开宏: (t) => t, ...额外,",
  "});",
  "",
  "const 原I = console.info, 原T = console.table, 原W = console.warn;",
  "console.info = () => {}; console.table = () => {}; console.warn = () => {};",
  "let r;",
  "try { r = buildUpdateMessages(造输入({})); } finally { console.info = 原I; console.table = 原T; console.warn = 原W; }",
  "const 内容表 = r.零件内容 ?? {};",
  "const 名到代 = Object.fromEntries(零件表.map(件 => [件.名, 件.代号]));",
  "const 取内容 = (名) => String(内容表[名到代[名] ?? ''] ?? '');",
  "const 现在产物 = r.messages[0].content;",
  "const NL = String.fromCharCode(10);",
  "",
  "/** 渲染：占位符独占一行时吃掉该行换行 */",
  "function 渲染(模板) {",
  "  const 行们 = 模板.split(NL);",
  "  const 出 = [];",
  "  for (const 行 of 行们) {",
  "    const m = 行.match(/^\\{\\{彼方:(.+?)\\}\\}$/);",
  "    if (m) { 出.push({ 文: 取内容(m[1]), 吃: true }); continue; }",
  "    出.push({ 文: 行.replace(/\\{\\{彼方:(.+?)\\}\\}/g, (_, 名) => 取内容(名)), 吃: false });",
  "  }",
  "  let 结果 = '';",
  "  for (let i = 0; i < 出.length; i++) {",
  "    结果 += 出[i].文;",
  "    if (i < 出.length - 1 && !出[i].吃) 结果 += NL;",
  "  }",
  "  return 结果;",
  "}",
  "",
  "const 名们 = ['身份句','核心原则','NPC 判定','字段规格','输出要求'];",
  "const 模板A = 名们.map(n => '{{彼方:' + n + '}}').join(NL);",
  "const 出A = 渲染(模板A);",
  "console.log('现在产物长度', 现在产物.length);",
  "console.log('模板A(吃换行) 长度', 出A.length, '| 逐字节相同?', 出A === 现在产物);",
  "if (出A !== 现在产物) {",
  "  for (let i = 0; i < Math.max(出A.length, 现在产物.length); i++) {",
  "    if (出A[i] !== 现在产物[i]) {",
  "      console.log('首个差异 @', i);",
  "      console.log('  现在:', JSON.stringify(现在产物.slice(Math.max(0,i-25), i+25)));",
  "      console.log('  模板:', JSON.stringify(出A.slice(Math.max(0,i-25), i+25)));",
  "      break;",
  "    }",
  "  }",
  "}",
  "const 模板B = 名们.map(n => '{{彼方:' + n + '}}').join(NL + NL);",
  "const 出B = 渲染(模板B);",
  "console.log('模板B(加空行) 长度', 出B.length, '| 相同?', 出B === 现在产物, '| 多出', 出B.length - 现在产物.length, '字');",
  "",
  "// ── 全部零件（含数据段）──",
  "const 全名们 = 零件表.map(件 => 件.名);",
  "const 模板全 = 全名们.map(n => '{{彼方:' + n + '}}').join(NL);",
  "const 出全 = 渲染(模板全);",
  "const 现在全文 = r.messages.map(m => m.content).join(NL);",
  "console.log('');",
  "console.log('零件数', 全名们.length, '| 现在全文', 现在全文.length, '| 模板全渲染', 出全.length, '| 相同?', 出全 === 现在全文);",
  "if (出全 !== 现在全文) {",
  "  for (let i = 0; i < Math.max(出全.length, 现在全文.length); i++) {",
  "    if (出全[i] !== 现在全文[i]) {",
  "      console.log('首个差异 @', i);",
  "      console.log('  现在:', JSON.stringify(现在全文.slice(Math.max(0,i-40), i+40)));",
  "      console.log('  模板:', JSON.stringify(出全.slice(Math.max(0,i-40), i+40)));",
  "      break;",
  "    }",
  "  }",
  "}",
  "",
  "// ── 带场景判断 ──",
  "const 原I2 = console.info, 原T2 = console.table, 原W2 = console.warn;",
  "console.info = () => {}; console.table = () => {}; console.warn = () => {};",
  "let r2;",
  "try { r2 = buildUpdateMessages(造输入({ context: '玩家走进广场' })); }",
  "finally { console.info = 原I2; console.table = 原T2; console.warn = 原W2; }",
  "const 内容表2 = r2.零件内容 ?? {};",
  "const 取内容2 = (名) => String(内容表2[名到代[名] ?? ''] ?? '');",
  "function 渲染2(模板) {",
  "  const 行们 = 模板.split(NL);",
  "  const 出 = [];",
  "  for (const 行 of 行们) {",
  "    const m = 行.match(/^\\{\\{彼方:(.+?)\\}\\}$/);",
  "    if (m) { 出.push({ 文: 取内容2(m[1]), 吃: true }); continue; }",
  "    出.push({ 文: 行.replace(/\\{\\{彼方:(.+?)\\}\\}/g, (_, 名) => 取内容2(名)), 吃: false });",
  "  }",
  "  let 结果 = '';",
  "  for (let i = 0; i < 出.length; i++) {",
  "    结果 += 出[i].文;",
  "    if (i < 出.length - 1 && !出[i].吃) 结果 += NL;",
  "  }",
  "  return 结果;",
  "}",
  "const 出全2 = 渲染2(模板全);",
  "const 现在全文2 = r2.messages.map(m => m.content).join(NL);",
  "console.log('带场景: 现在', 现在全文2.length, '模板', 出全2.length, '相同?', 出全2 === 现在全文2);",
  "if (出全2 !== 现在全文2) {",
  "  for (let i = 0; i < Math.max(出全2.length, 现在全文2.length); i++) {",
  "    if (出全2[i] !== 现在全文2[i]) {",
  "      console.log('首个差异 @', i);",
  "      console.log('  现在:', JSON.stringify(现在全文2.slice(Math.max(0,i-40), i+40)));",
  "      console.log('  模板:', JSON.stringify(出全2.slice(Math.max(0,i-40), i+40)));",
  "      break;",
  "    }",
  "  }",
  "}",
].join('\n');

writeFileSync(入口, 源码);

await buildTest(入口, 产物);
await import(new URL(`file:///${产物.replace(/\\/g, '/')}`).href);
